#include <stdio.h>
#include <string.h>
/* ex01：CRC 校验——模 2 除法求余数
 * 生成多项式 G(x) = x^4 + x + 1 -> 二进制 10011（共 5 位）
 * 步骤：数据末尾补 (阶数) 个 0 -> 用 G 做模 2 除法 -> 余数就是 FCS
 * 模 2 除法：逐位异或，不借位、不进位，就是纯 XOR。*/
static void crc_remainder(const char *data, const char *gen, char *out) {
    int g = (int)strlen(gen);
    char buf[128];
    strcpy(buf, data);
    for (int i = 0; i < g - 1; i++) strcat(buf, "0");   /* 补 g-1 个 0 */
    int len = (int)strlen(buf);

    printf("被除数（补 0 后）: %s\n", buf);
    for (int i = 0; i <= len - g; i++) {
        if (buf[i] == '1') {                            /* 首位为 1 才需要除 */
            for (int j = 0; j < g; j++)
                buf[i + j] = (buf[i + j] == gen[j]) ? '0' : '1';
            printf("  第 %d 步异或后: %s\n", i + 1, buf);
        }
    }
    printf("最终余数（FCS）: %s\n", buf + len - (g - 1));
    strcpy(out, buf + len - (g - 1));
}

int main(void) {
    const char *data = "1101011011";        /* 10 bit 数据 */
    const char *gen  = "10011";             /* G(x)=x^4+x+1 */
    char fcs[16], frame[128];

    printf("数据: %s，生成多项式 G(x)=x^4+x+1 -> %s\n", data, gen);
    printf("------------------------------------------------------------\n");
    crc_remainder(data, gen, fcs);

    /* 发送的帧 = 数据 + FCS */
    sprintf(frame, "%s%s", data, fcs);
    printf("\n发送的帧: %s（%d bit）\n", frame, (int)strlen(frame));

    /* 接收端用同样的 G 去除整帧，余数应为全 0 */
    char check[16];
    printf("\n接收端校验（整帧除以 G）:\n");
    crc_remainder(frame, gen, check);
    printf("校验余数 = %s -> %s\n", check,
           strcmp(check, "0000") == 0 ? "全 0，判定无差错" : "非 0，判定有差错");
    return 0;
}
